"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[9696],{79704:(e,t,h)=>{h.r(t),h.d(t,{assets:()=>r,contentTitle:()=>a,default:()=>c,frontMatter:()=>i,metadata:()=>o,toc:()=>d});var s=h(31085),n=h(71184);const i={sidebar_position:26,slug:"/bible/Matthew/Matthew_26",title:"Matthew 26",hide_table_of_contents:!0},a="Matthew",o={id:"bible/Matthew/Matthew 26",title:"Matthew 26",description:"Chapter 26",source:"@site/docs/bible/Matthew/Matthew 26.md",sourceDirName:"bible/Matthew",slug:"/bible/Matthew/Matthew_26",permalink:"/docs/bible/Matthew/Matthew_26",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/docs/bible/Matthew/Matthew 26.md",tags:[],version:"current",sidebarPosition:26,frontMatter:{sidebar_position:26,slug:"/bible/Matthew/Matthew_26",title:"Matthew 26",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Matthew 25",permalink:"/docs/bible/Matthew/Matthew_25"},next:{title:"Matthew 27",permalink:"/docs/bible/Matthew/Matthew_27"}},r={},d=[{value:"Chapter 26",id:"chapter-26",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,n.R)(),...e.components},{BibleText:h}=t;return h||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.h1,{id:"matthew",children:"Matthew"}),"\n",(0,s.jsx)(t.h2,{id:"chapter-26",children:"Chapter 26"}),"\n",(0,s.jsx)(t.p,{children:"The Jews conspire against Christ.  He is anointed by Mary.  The treason of Judas.  The last supper.  The prayer in the garden.  The apprehension of our Lord.  His treatment in the house of Caiphas."}),"\n",(0,s.jsx)(h,{verse:1,children:"And it came to pass, when Jesus had ended all these words, he said to his disciples:"}),"\n",(0,s.jsx)(h,{verse:2,children:"You know that after two days shall be the pasch: and the Son of man shall be delivered up to be crucified."}),"\n",(0,s.jsx)(h,{verse:3,children:"Then were gathered together the chief priests and ancients of the people, into the court of the high priest, who was called Caiphas:"}),"\n",(0,s.jsx)(h,{verse:4,children:"And they consulted together that by subtilty they might apprehend Jesus and put him to death."}),"\n",(0,s.jsx)(h,{verse:5,children:"But they said: Not on the festival day, lest perhaps there should be a tumult among the people."}),"\n",(0,s.jsx)(h,{verse:6,children:"And when Jesus was in Bethania, in the house of Simon the leper,"}),"\n",(0,s.jsx)(h,{verse:7,children:"There came to him a woman having an alabaster box of precious ointment and poured it on his head as he was at table."}),"\n",(0,s.jsx)(h,{verse:8,children:"And the disciples seeing it had indignation, saying: To what purpose is this waste?"}),"\n",(0,s.jsx)(h,{verse:9,children:"For this might have been sold for much and given to the poor."}),"\n",(0,s.jsx)(h,{verse:10,children:"And Jesus knowing it, said to them: Why do you trouble this woman? For she hath wrought a good work upon me."}),"\n",(0,s.jsx)(h,{verse:11,children:"For the poor you have always with you: but me you have not always."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Me you have not always...Viz., in a visible manner, as when conversant here on earth; and as we have the poor, whom we may daily assist and relieve."})}),"\n",(0,s.jsx)(h,{verse:12,children:"For she in pouring this ointment on my body hath done it for my burial."}),"\n",(0,s.jsx)(h,{verse:13,children:"Amen I say to you, wheresoever this gospel shall be preached in the whole world, that also which she hath done shall be told for a memory of her."}),"\n",(0,s.jsx)(h,{verse:14,children:"Then went one of the twelve, who was called Judas Iscariot, to the chief priests."}),"\n",(0,s.jsx)(h,{verse:15,children:"And said to them: What will you give me, and I will deliver him unto you? But they appointed him thirty pieces of silver."}),"\n",(0,s.jsx)(h,{verse:16,children:"And from thenceforth he sought opportunity to betray him."}),"\n",(0,s.jsx)(h,{verse:17,children:"And on the first day of the Azymes, the disciples came to Jesus, saying: Where wilt thou that we prepare for thee to eat the pasch?"}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Azymes...Feast of the unleavened bread. Pasch...The paschal lamb."})}),"\n",(0,s.jsx)(h,{verse:18,children:"But Jesus said: Go ye into the city to a certain man and say to him: The master saith, My time is near at hand. With thee I make the pasch with my disciples."}),"\n",(0,s.jsx)(h,{verse:19,children:"And the disciples did as Jesus appointed to them: and they prepared the pasch."}),"\n",(0,s.jsx)(h,{verse:20,children:"But when it was evening, he sat down with his twelve disciples."}),"\n",(0,s.jsx)(h,{verse:21,children:"And whilst they were eating, he said: Amen I say to you that one of you is about to betray me."}),"\n",(0,s.jsx)(h,{verse:22,children:"And they being very much troubled began every one to say: Is it I, Lord?"}),"\n",(0,s.jsx)(h,{verse:23,children:"But he answering said: He that dippeth his hand with me in the dish, he shall betray me."}),"\n",(0,s.jsx)(h,{verse:24,children:"The Son of man indeed goeth, as it is written of him. But woe to that man by whom the Son of man shall be betrayed. It were better for him, if that man had not been born."}),"\n",(0,s.jsx)(h,{verse:25,children:"And Judas that betrayed him answering, said: Is it I, Rabbi? He saith to him: Thou hast said it."}),"\n",(0,s.jsx)(h,{verse:26,children:"And whilst they were at supper, Jesus took bread and blessed and broke and gave to his disciples and said: Take ye and eat. This is my body."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: This is my body...He does not say, This is the figure of my body--but This is my body. (2 Council of Nice, Act. 6.) Neither does he say in this, or with this is my body; but absolutely, This is my body: which plainly implies transubstantiation."})}),"\n",(0,s.jsx)(h,{verse:27,children:"And taking the chalice, he gave thanks and gave to them, saying: Drink ye all of this."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Drink ye all of this...This was spoken to the twelve apostles; who were the all then present; and they all drank of it, says St. Mark 14. 23. But it no ways follows from these words spoken to the apostles, that all the faithful are here commanded to drink of the chalice; any more than that all the faithful are commanded to consecrate, offer and administer this sacrament; because Christ upon this same occasion, and at the same time, bid the apostles do so; in these words, St. Luke 22. 19, Do this for a commemoration of me."})}),"\n",(0,s.jsx)(h,{verse:28,children:"For this is my blood of the new testament, which shall be shed for many unto remission of sins."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Blood of the new testament...As the old testament was dedicated with the blood of victims, by Moses, in these words: This is the blood of the testament, etc., Heb. 9. 20; so here is the dedication and institution of the new testament, in the blood of Christ, here mystically shed by these words: This is the blood of the new testament, etc."})}),"\n",(0,s.jsx)(h,{verse:29,children:"And I say to you, I will not drink from henceforth of this fruit of the vine until that day when I shall drink it with you new in the kingdom of my Father."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Fruit of the vine...These words, by the account of St. Luke 26:22. 18, were not spoken of the sacramental cup, but of the wine that was drunk with the paschal lamb. Though the sacramental cup might also be called the fruit of the vine, because it was consecrated from wine, and retains the likeness, and all the accidents or qualities of wine."})}),"\n",(0,s.jsx)(h,{verse:30,children:"And a hymn being said, they went out unto mount Olivet."}),"\n",(0,s.jsx)(h,{verse:31,children:"Then Jesus saith to them: All you shall be scandalized in me this night. For it is written: I will strike the shepherd: and the sheep of the flock shall be dispersed."}),"\n",(0,s.jsx)(t.admonition,{type:"note",children:(0,s.jsx)(t.p,{children:"Note 1: Scandalized in me, etc...Forasmuch as my being apprehended shall make you all run away and forsake me."})}),"\n",(0,s.jsx)(h,{verse:32,children:"But after I shall be risen again, I will go before you into Galilee."}),"\n",(0,s.jsx)(h,{verse:33,children:"And Peter answering, said to him: Although all shall be scandalized in thee, I will never be scandalized."}),"\n",(0,s.jsx)(h,{verse:34,children:"Jesus said to him: Amen I say to thee that in this night before the cock crow, thou wilt deny me thrice."}),"\n",(0,s.jsx)(h,{verse:35,children:"Peter saith to him: Yea, though I should die with thee, I will not deny thee. And in like manner said all the disciples."}),"\n",(0,s.jsx)(h,{verse:36,children:"Then Jesus came with them into a country place which is called Gethsemani. And he said to his disciples: Sit you here, till I go yonder and pray."}),"\n",(0,s.jsx)(h,{verse:37,children:"And taking with him Peter and the two sons of Zebedee, he began to grow sorrowful and to be sad."}),"\n",(0,s.jsx)(h,{verse:38,children:"Then he saith to them: My soul is sorrowful even unto death. Stay you here and watch with me."}),"\n",(0,s.jsx)(h,{verse:39,children:"And going a little further, he fell upon his face, praying and saying: My Father, if it be possible, let this chalice pass from me. Nevertheless, not as I will but as thou wilt."}),"\n",(0,s.jsx)(h,{verse:40,children:"And he cometh to his disciples and findeth them asleep. And he saith to Peter: What? Could you not watch one hour with me?"}),"\n",(0,s.jsx)(h,{verse:41,children:"Watch ye: and pray that ye enter not into temptation. The spirit indeed is willing, but the flesh is weak."}),"\n",(0,s.jsx)(h,{verse:42,children:"Again the second time, he went and prayed, saying: My Father, if this chalice may not pass away, but I must drink it, thy will be done."}),"\n",(0,s.jsx)(h,{verse:43,children:"And he cometh again and findeth them sleeping: for their eyes were heavy."}),"\n",(0,s.jsx)(h,{verse:44,children:"And leaving them, he went again: and he prayed the third time, saying the selfsame word."}),"\n",(0,s.jsx)(h,{verse:45,children:"Then he cometh to his disciples and said to them: Sleep ye now and take your rest. Behold the hour is at hand: and the Son of man shall be betrayed into the hands of sinners."}),"\n",(0,s.jsx)(h,{verse:46,children:"Rise: let us go. Behold he is at hand that will betray me."}),"\n",(0,s.jsx)(h,{verse:47,children:"As he yet spoke, behold Judas, one of the twelve, came, and with him a great multitude with swords and clubs, sent from the chief priests and the ancients of the people."}),"\n",(0,s.jsx)(h,{verse:48,children:"And he that betrayed him gave them a sign, saying: Whomsoever I shall kiss, that is he. Hold him fast."}),"\n",(0,s.jsx)(h,{verse:49,children:"And forthwith coming to Jesus, he said: Hail, Rabbi. And he kissed him."}),"\n",(0,s.jsx)(h,{verse:50,children:"And Jesus said to him: Friend, whereto art thou come? Then they came up and laid hands on Jesus and held him."}),"\n",(0,s.jsx)(h,{verse:51,children:"And behold one of them that were with Jesus, stretching forth his hand, drew out his sword: and striking the servant of the high priest, cut off his ear."}),"\n",(0,s.jsx)(h,{verse:52,children:"Then Jesus saith to him: Put up again thy sword into its place: for all that take the sword shall perish with the sword."}),"\n",(0,s.jsx)(h,{verse:53,children:"Thinkest thou that I cannot ask my Father, and he will give me presently more than twelve legions of angels?"}),"\n",(0,s.jsx)(h,{verse:54,children:"How then shall the scriptures be fulfilled, that so it must be done?"}),"\n",(0,s.jsx)(h,{verse:55,children:"In that same hour, Jesus said to the multitudes: You are come out, as it were to a robber, with swords and clubs to apprehend me. I sat daily with you, teaching in the temple: and you laid not hands on me."}),"\n",(0,s.jsx)(h,{verse:56,children:"Now all this was done that the scriptures of the prophets might be fulfilled. Then the disciples, all leaving him, fled."}),"\n",(0,s.jsx)(h,{verse:57,children:"But they holding Jesus led him to Caiphas the high priest, where the scribes and the ancients were assembled."}),"\n",(0,s.jsx)(h,{verse:58,children:"And Peter followed him afar off, even to the court of the high priest, And going in, he sat with the servants, that he might see the end."}),"\n",(0,s.jsx)(h,{verse:59,children:"And the chief priests and the whole council sought false witness against Jesus, that they might put him to death."}),"\n",(0,s.jsx)(h,{verse:60,children:"And they found not, whereas many false witnesses had come in. And last of all there came two false witnesses:"}),"\n",(0,s.jsx)(h,{verse:61,children:"And they said: This man said, I am able to destroy the temple of God and after three days to rebuild it."}),"\n",(0,s.jsx)(h,{verse:62,children:"And the high priest rising up, said to him: Answerest thou nothing to the things which these witness against thee?"}),"\n",(0,s.jsx)(h,{verse:63,children:"But Jesus held his peace. And the high priest said to him: I adjure thee by the living God, that thou tell us if thou be the Christ the Son of God."}),"\n",(0,s.jsx)(h,{verse:64,children:"Jesus saith to him: Thou hast said it. Nevertheless I say to you, hereafter you shall see the Son of man sitting on the right hand of the power of God and coming in the clouds of heaven."}),"\n",(0,s.jsx)(h,{verse:65,children:"Then the high priest rent his garments, saying: He hath blasphemed: What further need have we of witnesses? Behold, now you have heard the blasphemy."}),"\n",(0,s.jsx)(h,{verse:66,children:"What think you? But they answering, said: He is guilty of death."}),"\n",(0,s.jsx)(h,{verse:67,children:"Then did they spit in his face and buffeted him. And others struck his face with the palms of their hands,"}),"\n",(0,s.jsx)(h,{verse:68,children:"Saying: Prophesy unto us, O Christ. Who is he that struck thee?"}),"\n",(0,s.jsx)(h,{verse:69,children:"But Peter sat without in the court. And there came to him a servant maid, saying: Thou also wast with Jesus the Galilean."}),"\n",(0,s.jsx)(h,{verse:70,children:"But he denied before them all, saying: I know not what thou sayest."}),"\n",(0,s.jsx)(h,{verse:71,children:"And as he went out of the gate, another maid saw him; and she saith to them that were there: This man also was with Jesus of Nazareth."}),"\n",(0,s.jsx)(h,{verse:72,children:"And again he denied with an oath: I know not the man."}),"\n",(0,s.jsx)(h,{verse:73,children:"And after a little while, they came that stood by and said to Peter: Surely thou also art one of them. For even thy speech doth discover thee."}),"\n",(0,s.jsx)(h,{verse:74,children:"Then he began to curse and to swear that he knew not the man. And immediately the cock crew."}),"\n",(0,s.jsx)(h,{verse:75,children:"And Peter remembered the word of Jesus which he had said: Before the cock crow, thou wilt deny me thrice. And going forth, he wept bitterly."})]})}function c(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},71184:(e,t,h)=>{h.d(t,{R:()=>a,x:()=>o});var s=h(14041);const n={},i=s.createContext(n);function a(e){const t=s.useContext(i);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:a(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);